public class HeaderBodyFooterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String regionName(javax.swing.JPanel panel, String region) {
        java.awt.LayoutManager lm = panel.getLayout();
        if (!(lm instanceof java.awt.BorderLayout)) {
            return "(no BorderLayout)";
        }
        java.awt.Component c = ((java.awt.BorderLayout) lm).getLayoutComponent(region);
        return c == null ? "(empty)" : String.valueOf(c.getName());
    }

    public static void main(String[] args) {
        try {
            HeaderBodyFooter panel = new HeaderBodyFooter();
            check("panel uses a BorderLayout", true,
                    panel.getLayout() instanceof java.awt.BorderLayout);
            check("NORTH holds the header", "header",
                    regionName(panel, java.awt.BorderLayout.NORTH));
            check("CENTER holds the body", "body",
                    regionName(panel, java.awt.BorderLayout.CENTER));
            check("SOUTH holds the footer", "footer",
                    regionName(panel, java.awt.BorderLayout.SOUTH));
            check("exactly three components added", 3, panel.getComponentCount());
            boolean centerIsTextArea = false;
            if (panel.getLayout() instanceof java.awt.BorderLayout) {
                java.awt.Component c = ((java.awt.BorderLayout) panel.getLayout())
                        .getLayoutComponent(java.awt.BorderLayout.CENTER);
                centerIsTextArea = c instanceof javax.swing.JTextArea;
            }
            check("CENTER component is the JTextArea", true, centerIsTextArea);
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

