import java.awt.BorderLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;

public class HeaderBodyFooter extends JPanel {

    private final JLabel header = new JLabel("My App");
    private final JTextArea body = new JTextArea("type here");
    private final JLabel footer = new JLabel("status: ready");

    public HeaderBodyFooter() {
        header.setName("header");
        body.setName("body");
        footer.setName("footer");
        setLayout(new BorderLayout());
        add(header, BorderLayout.NORTH);
        add(body, BorderLayout.CENTER);
        add(footer, BorderLayout.SOUTH);
    }
}
